/* Copied from get-convex/better-auth src/client/create-schema.ts at 3f41cbcf
 * (Apache-2.0, see ../../LICENSE). Qivo changed it:
 * - It also indexes a field that Better Auth marks `index: true`, and every
 *   table-level index Better Auth 1.7 declares, such as oauthClientResource's
 *   (clientId, resourceId). Better Auth 1.7 looks rows up by such fields.
 * - It uses no Node module or process.cwd(), which Convex's default runtime
 *   lacks and Qivo's runtime check refuses (the adapter imports it). The
 *   header names Qivo's own command and output, relative to the project root,
 *   since Better Auth 1.7's CLI passes an absolute path.
 * - Types replace `any`. */
import type { BetterAuthDBSchema, DBFieldAttribute } from 'better-auth/db'

/** Where Qivo keeps the generated schema, relative to the project root. */
const OUTPUT = 'convex/betterAuth/schema.generated.ts'

// Manually add fields to index on for schema generation,
// all fields in the schema specialFields are automatically indexed
export const indexFields: Record<string, (string | string[])[]> = {
  account: ['accountId', ['accountId', 'providerId'], ['providerId', 'userId']],
  rateLimit: ['key'],
  session: ['expiresAt', ['expiresAt', 'userId']],
  verification: ['expiresAt', 'identifier'],
  user: [['email', 'name'], 'name', 'userId'],
  oauthConsent: [['clientId', 'userId']],
}

/** The fields of each table that get an index of their own: the sortable,
 * unique, indexed and reference fields. */
const specialFields = (tables: BetterAuthDBSchema) =>
  Object.fromEntries(
    Object.entries(tables).map(([key, table]) => [
      key,
      Object.entries(table.fields)
        .filter(([, field]) => field.sortable || field.unique || field.index || field.references)
        .map(([fieldKey, field]) => field.fieldName ?? fieldKey),
    ]),
  )

/** Every index of each table, as lists of field names: the table's own
 * indexes, the manual ones above, then one per special field that no other
 * index starts with. */
const mergedIndexFields = (tables: BetterAuthDBSchema) => {
  const special = specialFields(tables)
  return Object.fromEntries(
    Object.entries(tables).map(([key, table]) => {
      const fieldName = (field: string) => table.fields[field]?.fieldName ?? field
      const schemaIndexes = table.indexes?.map((index) => index.fields.map(fieldName)) ?? []
      const manualIndexes = (indexFields[key] ?? []).map((index) =>
        typeof index === 'string' ? [fieldName(index)] : index.map(fieldName),
      )
      const indexes = [...schemaIndexes, ...manualIndexes]
      for (const field of special[key] ?? []) {
        if (!indexes.some((index) => index[0] === field)) indexes.push([field])
      }
      const names = new Set<string>()
      return [
        key,
        indexes
          .map((index) => [...index].sort())
          .filter((index) => {
            const name = index.join('_')
            if (names.has(name)) return false
            names.add(name)
            return true
          }),
      ]
    }),
  )
}

/** Writes the component schema for Better Auth's tables, for `npx auth generate`. */
export const createSchema = async ({
  file,
  tables,
}: {
  tables: BetterAuthDBSchema
  file?: string
}) => {
  // Anywhere else it could replace another schema, such as the app's.
  if (file && !file.replace(/\\/g, '/').endsWith(OUTPUT)) {
    throw new Error(`Generate the Better Auth schema to ${OUTPUT}.`)
  }
  const commandBlock =
    ' *   cd convex/betterAuth\n *   npx auth generate --output schema.generated.ts'

  let code: string = `/**
 * This file is auto-generated. Do not edit this file manually.
 * To regenerate the schema, from your project root:
 *
${commandBlock}
 *
 * To customize the schema, generate to an alternate file and import
 * the table definitions to your schema file. See
 * https://labs.convex.dev/better-auth/features/local-install#adding-custom-indexes.
 */

import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export const tables = {
`

  const allIndexes = mergedIndexFields(tables)
  for (const tableKey in tables) {
    const table = tables[tableKey]
    const modelName = table.modelName

    // No id fields in Convex schema
    const fields = Object.entries(table.fields).filter(([key]) => key !== 'id')

    const getType = (field: DBFieldAttribute) => {
      const typeMap: Record<string, string> = {
        string: 'v.string()',
        boolean: 'v.boolean()',
        number: 'v.number()',
        date: 'v.number()',
        json: 'v.string()',
        'number[]': 'v.array(v.number())',
        'string[]': 'v.array(v.string())',
      }
      return typeMap[String(field.type)]
    }

    const indexes = (allIndexes[tableKey] ?? []).map(
      (index) => `.index("${index.join('_')}", ${JSON.stringify(index)})`,
    )

    const schema = `${modelName}: defineTable({
${fields
  .map(([field, attr]) => {
    const type = getType(attr)
    const optional = (fieldSchema: string) =>
      attr.required ? fieldSchema : `v.optional(v.union(v.null(), ${fieldSchema}))`
    return `    ${attr.fieldName ?? field}: ${optional(type)},`
  })
  .join('\n')}
  })${indexes.length > 0 ? `\n    ${indexes.join('\n    ')}` : ''},\n`
    code += `  ${schema}`
  }

  code += `};

const schema = defineSchema(tables);

export default schema;
`

  return { code, path: file ?? './schema.ts', overwrite: true }
}
